-- 4. Paste repair (scripts/rls-local/strip-cr.sql): functions whose body picked up CR characters.
do $strip$
declare
  f record;
  fixed int := 0;
begin
  for f in
    select p.oid, n.nspname, p.proname
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname in ('public', 'private')
      and p.prokind = 'f'
      and position(E'\r' in p.prosrc) > 0
      and not exists (select 1 from pg_depend d where d.objid = p.oid and d.deptype = 'e')
  loop
    execute replace(pg_get_functiondef(f.oid), E'\r', '');
    fixed := fixed + 1;
    raise notice 'CR_STRIPPED %.%', f.nspname, f.proname;
  end loop;
  raise notice 'CR_STRIP_DONE functions_fixed=%', fixed;
end
$strip$;
insert into ffh_apply_results
select 3, 'paste repair: no function body contains CR', count(*) = 0, count(*)::text || ' left'
from pg_proc p join pg_namespace n on n.oid = p.pronamespace
where n.nspname in ('public', 'private') and position(E'\r' in p.prosrc) > 0;

